
(async () => {
  const DATA = {
    carrying: "",
    walking: "",
    turn: "",
    holdingDown: "",
    boxWalk: ""
  };

  const SOURCES = {
    carrying: "Carrying (1).fbx",
    walking: "Walking (1).fbx",
    turn: "Carrying Turn (1).fbx",
    holdingDown: "Holding Down.fbx",
    boxWalk: "Box Walk Arc.fbx"
  };

  const status = document.getElementById("status");
  const lumberStatus = document.getElementById("lumberStatus");
  const placeBtn = document.getElementById("logPlaceModeBtn");
  const hint = document.getElementById("logBuildHint");
  const hintTitle = document.getElementById("logBuildTitle");
  const hintText = document.getElementById("logBuildText");
  const mobileConfirm = document.getElementById("logConfirmMobile");
  const canvas = document.getElementById("c");

  const sleep = ms => new Promise(r=>setTimeout(r,ms));
  const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
  const wrap=a=>Math.atan2(Math.sin(a),Math.cos(a));

  async function gunzipB64(s){
    const bin=atob(s),raw=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)raw[i]=bin.charCodeAt(i);
    const ds=new DecompressionStream("gzip");
    return await new Response(new Blob([raw]).stream().pipeThrough(ds)).arrayBuffer();
  }

  async function importFirst(urls){
    let last;
    for(const u of urls){
      try{return await window.__LOCAL_IMPORT(u)}catch(e){last=e}
    }
    throw last||new Error("Falha ao carregar módulo 3D.");
  }

  async function waitGame(){
    for(let i=0;i<1000;i++){
      const g=window.gameReview;
      if(
        g?.scene && g?.camera && g?.player && g?.groundY &&
        g?.keys && g?.trueFirstPerson?.model &&
        g?.trueFirstPerson?.bones?.lHand &&
        g?.trueFirstPerson?.bones?.rHand &&
        window.gameLumber
      ) return g;
      await sleep(20);
    }
    throw new Error("Jogo/lenhador/rig não ficaram disponíveis.");
  }

  function stripForCarry(source,{armsOnly=false}={}){
    const clip=source.clone();
    clip.tracks=clip.tracks.filter(track=>{
      const n=track.name;
      if(!/\.quaternion$/i.test(n))return false;

      // Camera/look continues to control the actual head.
      if(/(Head|Neck)\.quaternion$/i.test(n))return false;

      // Positioning mode uses BOTH arms because the trunk is held in front.
      if(armsOnly){
        return /(LeftShoulder|LeftArm|LeftForeArm|LeftHand|RightShoulder|RightArm|RightForeArm|RightHand)\.quaternion$/i.test(n)
          && !/Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(n);
      }

      return !/Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(n);
    });
    clip.resetDuration();
    return clip;
  }

  // Shoulder carry is different from positioning:
  // Box Walk Arc is only allowed to control the LEFT carrying arm.
  // The RIGHT shoulder/arm/forearm/hand remain on the normal game idle/walk
  // animation, so the right arm does not stay lifted in front of the camera.
  function shoulderWalkClip(source){
    const clip=source.clone();
    clip.tracks=clip.tracks.filter(track=>{
      const n=track.name;
      if(!/\.quaternion$/i.test(n))return false;
      if(/(Head|Neck)\.quaternion$/i.test(n))return false;
      if(/RightShoulder|RightArm|RightForeArm|RightHand/i.test(n))return false;
      if(/Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(n))return false;
      return true;
    });
    clip.resetDuration();
    return clip;
  }

  function staticPoseClip(THREE,source,time){
    const tracks=[];
    for(const track of source.tracks){
      if(!/\.quaternion$/i.test(track.name))continue;

      // STOPPED WITH LOG ON SHOULDER:
      // ONLY the LEFT carrying arm is frozen in the extended carrying pose.
      // Legs, hips, spine, head and the RIGHT axe arm stay under normal idle.
      if(!/(LeftShoulder|LeftArm|LeftForeArm|LeftHand)\.quaternion$/i.test(track.name))continue;
      if(/Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(track.name))continue;

      const size=track.getValueSize();
      const buf=new Float32Array(size);
      track.createInterpolant(buf).evaluate(clamp(time,0,source.duration));
      tracks.push(new track.constructor(track.name,[0],Array.from(buf)));
    }
    return new THREE.AnimationClip("Box Walk Arc - Left Arm Extended Static",0.001,tracks);
  }

  function boneBySuffix(root,suffix){
    let found=null;
    root?.traverse?.(o=>{
      if(found||!o.isBone)return;
      const n=String(o.name||"").replace(/^mixamorig:/i,"");
      if(n===suffix||n.endsWith(suffix))found=o;
    });
    return found;
  }

  // Automatically inspect Box Walk Arc and find the frame where the LEFT arm
  // is most extended. This avoids guessing a timestamp and keeps the exact
  // carrying arm pose even when standing still.
  function findSafeExtendedLeftArmTime(source,root,eyeSocket,THREE){
    const bones={
      shoulder:boneBySuffix(root,"LeftShoulder"),
      arm:boneBySuffix(root,"LeftArm"),
      fore:boneBySuffix(root,"LeftForeArm"),
      hand:boneBySuffix(root,"LeftHand")
    };
    if(!bones.shoulder||!bones.arm||!bones.fore||!bones.hand){
      return Math.min(.20,source.duration*.20);
    }

    const tracked=[
      ["LeftShoulder",bones.shoulder],
      ["LeftArm",bones.arm],
      ["LeftForeArm",bones.fore],
      ["LeftHand",bones.hand]
    ];
    const base=new Map(tracked.map(([,b])=>[b,b.quaternion.clone()]));

    const shoulderW=new THREE.Vector3();
    const handW=new THREE.Vector3();
    const eyeW=new THREE.Vector3();
    const shoulderL=new THREE.Vector3();
    const handL=new THREE.Vector3();

    let bestTime=Math.min(.20,source.duration*.20);
    let bestScore=-Infinity;
    const samples=48;

    for(let i=0;i<=samples;i++){
      const t=source.duration*(i/samples);

      for(const [suffix,bone] of tracked){
        const track=source.tracks.find(tr=>
          /\.quaternion$/i.test(tr.name) &&
          !/Hand(Thumb|Index|Middle|Ring|Pinky)/i.test(tr.name) &&
          tr.name.includes(suffix)
        );
        if(!track)continue;

        const buf=new Float32Array(4);
        track.createInterpolant(buf).evaluate(t);
        bone.quaternion.set(buf[0],buf[1],buf[2],buf[3]);
      }

      root.updateMatrixWorld(true);
      bones.shoulder.getWorldPosition(shoulderW);
      bones.hand.getWorldPosition(handW);
      eyeSocket?.getWorldPosition?.(eyeW);

      shoulderL.copy(shoulderW);
      handL.copy(handW);
      root.worldToLocal(shoulderL);
      root.worldToLocal(handL);

      const extension=shoulderW.distanceTo(handW);
      const eyeClearance=eyeSocket ? handW.distanceTo(eyeW) : 1.0;

      // Detect which local-X side the left shoulder lives on and require
      // the left hand to remain on that same side instead of crossing face.
      const sideSign=Math.sign(shoulderL.x)||1;
      const outward=sideSign*(handL.x-shoulderL.x);
      const crossBody=sideSign*handL.x < 0 ? Math.abs(handL.x) : 0;

      // A carry support arm should be around shoulder height or below it,
      // never over the head / through the first-person camera.
      const aboveShoulder=Math.max(0,handW.y-shoulderW.y-.12);
      const tooLow=Math.max(0,shoulderW.y-handW.y-.62);

      // Reject outright dangerous first-person poses.
      if(eyeClearance<.52) continue;
      if(crossBody>.04) continue;
      if(aboveShoulder>.18) continue;

      const score=
        extension*2.2 +
        Math.max(0,outward)*1.8 +
        eyeClearance*.55 -
        aboveShoulder*4.0 -
        tooLow*1.2 -
        crossBody*6.0;

      if(score>bestScore){
        bestScore=score;
        bestTime=t;
      }
    }

    for(const [bone,q] of base)bone.quaternion.copy(q);
    root.updateMatrixWorld(true);

    return bestTime;
  }

  try{
    const game=await waitGame();
    const tfp=game.trueFirstPerson;
    const scene=game.scene;
    const player=game.player;

    const [THREE,loaderMod,bCarry,bWalk,bTurn,bDown,bBox]=await Promise.all([
      importFirst([
        window.FLORESTA_MODULES.three,
        window.FLORESTA_MODULES.three
      ]),
      importFirst([
        window.FLORESTA_MODULES.FBXLoader,
        window.FLORESTA_MODULES.FBXLoader
      ]),
      gunzipB64(DATA.carrying),
      gunzipB64(DATA.walking),
      gunzipB64(DATA.turn),
      gunzipB64(DATA.holdingDown),
      gunzipB64(DATA.boxWalk)
    ]);

    const {FBXLoader}=loaderMod;
    const loader=new FBXLoader();
    const parsed={
      carrying:loader.parse(bCarry,""),
      walking:loader.parse(bWalk,""),
      turn:loader.parse(bTurn,""),
      holdingDown:loader.parse(bDown,""),
      boxWalk:loader.parse(bBox,"")
    };

    for(const [k,obj] of Object.entries(parsed)){
      if(!obj.animations?.length)throw new Error(`${SOURCES[k]} não contém animação.`);
    }

    const clips={
      carrying:stripForCarry(parsed.carrying.animations[0]),
      walking:stripForCarry(parsed.walking.animations[0]),
      turn:stripForCarry(parsed.turn.animations[0]),
      holdingDown:stripForCarry(parsed.holdingDown.animations[0]),
      boxWalk:shoulderWalkClip(parsed.boxWalk.animations[0])
    };
    clips.carrying.name="Carrying - Positioning";
    clips.walking.name="Walking - Positioning";
    clips.turn.name="Carrying Turn - Positioning";
    clips.holdingDown.name="Holding Down - Place Log";
    clips.boxWalk.name="Box Walk Arc - Left Shoulder Walk / Right Arm Free";

    const extendedLeftArmTime=findSafeExtendedLeftArmTime(
      parsed.boxWalk.animations[0],
      tfp.visibleRoot,
      tfp.eyeSocket, THREE
    );

    const armsIdleClip=staticPoseClip(
      THREE,
      parsed.boxWalk.animations[0],
      extendedLeftArmTime
    );

    const mixer=new THREE.AnimationMixer(tfp.model);
    const actions={
      carrying:mixer.clipAction(clips.carrying),
      walking:mixer.clipAction(clips.walking),
      turn:mixer.clipAction(clips.turn),
      holdingDown:mixer.clipAction(clips.holdingDown),
      boxWalk:mixer.clipAction(clips.boxWalk),
      shoulderIdle:mixer.clipAction(armsIdleClip)
    };

    actions.shoulderIdle.setEffectiveWeight(1);

    actions.carrying.setLoop(THREE.LoopRepeat,Infinity);
    actions.walking.setLoop(THREE.LoopRepeat,Infinity);
    actions.boxWalk.setLoop(THREE.LoopRepeat,Infinity);
    actions.turn.setLoop(THREE.LoopOnce,1);
    actions.turn.clampWhenFinished=true;
    actions.holdingDown.setLoop(THREE.LoopOnce,1);
    actions.holdingDown.clampWhenFinished=true;
    actions.shoulderIdle.setLoop(THREE.LoopRepeat,Infinity);

    let currentAction=null;
    let currentKey="";
    let positioning=false;
    let placing=false;
    let placedThisAnimation=false;
    let frozenPlacement=null;
    let ghost=null;
    let lastTime=performance.now();
    let lastYaw=player.yaw;
    let turnCooldown=0;
    let turnActive=false;
    let torchWasEquipped=false;
    let rightHandItemBeforePositioning=null;
    let lastCarryingState=false;
    let placementValid=true;
    let placementBlockReason="";

    const lHand=tfp.bones.lHand;
    const rHand=tfp.bones.rHand;
    let lShoulder=null;
    tfp.visibleRoot.traverse(o=>{
      if(!lShoulder&&o.isBone&&/LeftShoulder$/i.test(String(o.name).replace("mixamorig:","")))lShoulder=o;
    });
    lShoulder=lShoulder||tfp.bones.lArm;

    const wpL=new THREE.Vector3(),wpR=new THREE.Vector3(),wpS=new THREE.Vector3();
    const eye=new THREE.Vector3(),mid=new THREE.Vector3();
    const axis=new THREE.Vector3(),right=new THREE.Vector3(),forward=new THREE.Vector3(),up=new THREE.Vector3(0,1,0);
    const q=new THREE.Quaternion(),camPos=new THREE.Vector3();

    function isMoving(){
      const k=game.keys;
      return !!(
        k.has("KeyW")||k.has("KeyA")||k.has("KeyS")||k.has("KeyD")||
        k.has("ArrowUp")||k.has("ArrowDown")||k.has("ArrowLeft")||k.has("ArrowRight")||
        Math.hypot(game.stick?.x||0,game.stick?.y||0)>.05
      );
    }

    function stopAll(){
      for(const a of Object.values(actions))a.stop();
      currentAction=null;
      currentKey="";
    }

    function useAction(key,restart=false){
      const next=actions[key];
      if(!next)return;
      if(currentKey===key&&!restart)return;

      if(currentAction)currentAction.stop();
      next.reset();
      next.enabled=true;
      next.setEffectiveWeight(1);
      next.setEffectiveTimeScale(1);
      next.play();

      currentAction=next;
      currentKey=key;
    }

    function stowTorch(){
      if(!game.isEquipped?.())return;
      torchWasEquipped=true;
      document.getElementById("equipBtn")?.click();
    }

    function restoreTorch(){
      if(torchWasEquipped&&!game.isEquipped?.()){
        document.getElementById("equipBtn")?.click();
      }
      torchWasEquipped=false;
    }

    // Shoulder carry: RIGHT hand keeps the axe normally.
    // Two-hand positioning: the axe is temporarily stored so both hands
    // can follow Carrying / Walking / Carrying Turn / Holding Down.
    function stowAxeForPositioning(){
      const current=window.gameRightHand?.current;
      if(current==="axe" || current==="rock" || current==="hammer"){
        rightHandItemBeforePositioning=current;
        window.gameRightHand.unequip();
      }
    }

    function restoreAxeAfterPositioning(){
      const item=rightHandItemBeforePositioning;
      rightHandItemBeforePositioning=null;
      if(item && window.gameRightHand?.current!==item){
        window.gameRightHand?.equip?.(item);
      }
    }

    function setButtonState(){
      const carrying=!!window.gameLumber?.carrying;
      placeBtn?.classList.toggle("visible",carrying&&!placing);
      placeBtn?.classList.toggle("active",positioning);
      if(placeBtn){
        placeBtn.textContent=positioning?"Cancelar posicionamento (G)":"Posicionar tronco (G)";
      }
      hint?.classList.toggle("visible",positioning||placing);
      mobileConfirm?.classList.toggle("visible",positioning&&!placing);
    }

    function cloneGhost(mesh){
      const g=mesh.clone(true);
      g.name="LogPlacementPreview";
      g.traverse(o=>{
        if(!o.isMesh)return;
        o.castShadow=false;
        o.receiveShadow=false;
        const mats=Array.isArray(o.material)?o.material:[o.material];
        const clones=mats.map(m=>{
          const n=m.clone();
          n.transparent=true;
          n.opacity=.34;
          n.depthWrite=false;
          n.color?.lerp?.(new THREE.Color(0x72df9a),.58);
          n.emissive?.setHex?.(0x12351f);
          n.emissiveIntensity=.25;
          return n;
        });
        o.material=Array.isArray(o.material)?clones:clones[0];
      });
      scene.add(g);
      return g;
    }

    function ensureGhost(){
      const mesh=window.gameLumber?.carriedMesh;
      if(!mesh)return null;
      if(!ghost)ghost=cloneGhost(mesh);
      return ghost;
    }

    function removeGhost(){
      if(!ghost)return;
      scene.remove(ghost);
      ghost.traverse(o=>{
        if(o.isMesh){
          o.geometry?.dispose?.();
          const mats=Array.isArray(o.material)?o.material:[o.material];
          mats.forEach(m=>m?.dispose?.());
        }
      });
      ghost=null;
    }

    function computePlacement(){
      const mesh=window.gameLumber?.carriedMesh;
      if(!mesh)return null;

      const yaw=player.yaw;
      forward.set(-Math.sin(yaw),0,-Math.cos(yaw)).normalize();
      right.set(Math.cos(yaw),0,-Math.sin(yaw)).normalize();

      const distance=2.65;
      const len=mesh.userData.length||3.1;
      const rad=mesh.userData.radius||.22;

      const cx=player.x+forward.x*distance;
      const cz=player.z+forward.z*distance;

      // For now only horizontal placement. The long axis lies across the
      // player's view, and both endpoints are sampled against the terrain.
      const ex=right.x*(len*.5);
      const ez=right.z*(len*.5);
      const x0=cx-ex,z0=cz-ez;
      const x1=cx+ex,z1=cz+ez;
      const y0=game.groundY(x0,z0)+rad*1.02;
      const y1=game.groundY(x1,z1)+rad*1.02;

      const a=new THREE.Vector3(x0,y0,z0);
      const b=new THREE.Vector3(x1,y1,z1);
      const center=a.clone().add(b).multiplyScalar(.5);
      const dir=b.clone().sub(a).normalize();
      const rot=new THREE.Quaternion().setFromUnitVectors(up,dir);

      const target={
        position:center,
        quaternion:rot,
        a,b,len,rad,
        snapped:false,
        snappedTo:null
      };

      // V58: nearby construction logs magnetically snap to true tangent
      // contact, so the player does not need pixel-perfect walking.
      return snapPlacementToLogs(target);
    }

    function pointSegmentDistanceXZ(px,pz,ax,az,bx,bz){
      const abx=bx-ax,abz=bz-az;
      const ab2=abx*abx+abz*abz;
      if(ab2<1e-8)return Math.hypot(px-ax,pz-az);
      const t=clamp(((px-ax)*abx+(pz-az)*abz)/ab2,0,1);
      const qx=ax+abx*t,qz=az+abz*t;
      return Math.hypot(px-qx,pz-qz);
    }

    function orientXZ(ax,az,bx,bz,cx,cz){
      return (bx-ax)*(cz-az)-(bz-az)*(cx-ax);
    }

    function segmentsIntersectXZ(a,b,c,d){
      const o1=orientXZ(a.x,a.z,b.x,b.z,c.x,c.z);
      const o2=orientXZ(a.x,a.z,b.x,b.z,d.x,d.z);
      const o3=orientXZ(c.x,c.z,d.x,d.z,a.x,a.z);
      const o4=orientXZ(c.x,c.z,d.x,d.z,b.x,b.z);

      if(
        ((o1>0&&o2<0)||(o1<0&&o2>0)) &&
        ((o3>0&&o4<0)||(o3<0&&o4>0))
      ) return true;

      return false;
    }

    function segmentDistanceXZ(a,b,c,d){
      if(segmentsIntersectXZ(a,b,c,d))return 0;
      return Math.min(
        pointSegmentDistanceXZ(a.x,a.z,c.x,c.z,d.x,d.z),
        pointSegmentDistanceXZ(b.x,b.z,c.x,c.z,d.x,d.z),
        pointSegmentDistanceXZ(c.x,c.z,a.x,a.z,b.x,b.z),
        pointSegmentDistanceXZ(d.x,d.z,a.x,a.z,b.x,b.z)
      );
    }

    const LOG_CONTACT_TOLERANCE=.0005;
    const LOG_SNAP_DISTANCE=.72;

    const snapTargetPoint=new THREE.Vector3();
    const snapOtherPoint=new THREE.Vector3();

    function closestPointOnSegmentXZ(
      px,pz,
      a,b,
      out
    ){
      const abx=b.x-a.x;
      const abz=b.z-a.z;
      const ab2=abx*abx+abz*abz;

      const t=
        ab2>.0000001
          ? clamp(
              (
                (px-a.x)*abx+
                (pz-a.z)*abz
              )/ab2,
              0,1
            )
          : 0;

      out.set(
        a.x+abx*t,
        a.y+(b.y-a.y)*t,
        a.z+abz*t
      );

      return out;
    }

    function closestSegmentPairXZ(
      a,b,
      c,d
    ){
      // If axes actually cross, the logs are penetrating/crossing.
      if(segmentsIntersectXZ(a,b,c,d)){
        return {
          distance:0,
          target:null,
          other:null
        };
      }

      const candidates=[];

      closestPointOnSegmentXZ(
        a.x,a.z,c,d,snapOtherPoint
      );
      candidates.push({
        distance:Math.hypot(
          a.x-snapOtherPoint.x,
          a.z-snapOtherPoint.z
        ),
        tx:a.x,tz:a.z,
        ox:snapOtherPoint.x,
        oz:snapOtherPoint.z
      });

      closestPointOnSegmentXZ(
        b.x,b.z,c,d,snapOtherPoint
      );
      candidates.push({
        distance:Math.hypot(
          b.x-snapOtherPoint.x,
          b.z-snapOtherPoint.z
        ),
        tx:b.x,tz:b.z,
        ox:snapOtherPoint.x,
        oz:snapOtherPoint.z
      });

      closestPointOnSegmentXZ(
        c.x,c.z,a,b,snapTargetPoint
      );
      candidates.push({
        distance:Math.hypot(
          snapTargetPoint.x-c.x,
          snapTargetPoint.z-c.z
        ),
        tx:snapTargetPoint.x,
        tz:snapTargetPoint.z,
        ox:c.x,oz:c.z
      });

      closestPointOnSegmentXZ(
        d.x,d.z,a,b,snapTargetPoint
      );
      candidates.push({
        distance:Math.hypot(
          snapTargetPoint.x-d.x,
          snapTargetPoint.z-d.z
        ),
        tx:snapTargetPoint.x,
        tz:snapTargetPoint.z,
        ox:d.x,oz:d.z
      });

      candidates.sort(
        (x,y)=>x.distance-y.distance
      );

      return candidates[0];
    }

    function refreshTargetVertical(target){
      target.a.y=
        game.groundY(
          target.a.x,
          target.a.z
        )+
        target.rad*1.02;

      target.b.y=
        game.groundY(
          target.b.x,
          target.b.z
        )+
        target.rad*1.02;

      target.position
        .copy(target.a)
        .add(target.b)
        .multiplyScalar(.5);

      const dir=
        target.b
          .clone()
          .sub(target.a)
          .normalize();

      target.quaternion
        .setFromUnitVectors(
          up,
          dir
        );

      return target;
    }

    function snapPlacementToLogs(target){
      if(!target)return target;

      const logs=
        window.gameLumber?.placedLogs||
        [];

      if(!logs.length)return target;

      let currentDx=
        target.b.x-target.a.x;

      let currentDz=
        target.b.z-target.a.z;

      let currentLen=
        Math.hypot(
          currentDx,
          currentDz
        );

      if(currentLen<.0001)return target;

      currentDx/=currentLen;
      currentDz/=currentLen;

      const centerX=
        (target.a.x+target.b.x)*.5;

      const centerZ=
        (target.a.z+target.b.z)*.5;

      let best=null;

      function consider(candidate){
        if(!candidate)return;
        if(!best||candidate.score<best.score){
          best=candidate;
        }
      }

      for(const mesh of logs){
        if(
          !mesh?.parent||
          mesh.visible===false
        )continue;

        const len=
          Math.max(
            .4,
            Number(mesh.userData.length)||3
          );

        const rad=
          Math.max(
            .10,
            Number(mesh.userData.radius)||.22
          );

        mesh.updateMatrixWorld(true);

        overlapA
          .set(0,-len*.5,0)
          .applyMatrix4(mesh.matrixWorld);

        overlapB
          .set(0, len*.5,0)
          .applyMatrix4(mesh.matrixWorld);

        let dx=
          overlapB.x-overlapA.x;

        let dz=
          overlapB.z-overlapA.z;

        const axisLen=
          Math.hypot(dx,dz);

        if(axisLen<.0001)continue;

        dx/=axisLen;
        dz/=axisLen;

        const rawDot=
          dx*currentDx+
          dz*currentDz;

        const absDot=Math.abs(rawDot);

        // -------- PARALLEL SIDE-BY-SIDE SNAP --------
        {
          let pdx=dx;
          let pdz=dz;

          if(rawDot<0){
            pdx=-pdx;
            pdz=-pdz;
          }

          const ax=overlapA.x;
          const az=overlapA.z;

          const along=
            (centerX-ax)*pdx+
            (centerZ-az)*pdz;

          const extra=
            target.len*.48+
            .45;

          if(
            along>=-extra&&
            along<=axisLen+extra
          ){
            const projectedX=
              ax+pdx*along;

            const projectedZ=
              az+pdz*along;

            let nx=-pdz;
            let nz= pdx;

            const sideDot=
              (centerX-projectedX)*nx+
              (centerZ-projectedZ)*nz;

            if(sideDot<0){
              nx=-nx;
              nz=-nz;
            }

            const currentSideDistance=
              Math.abs(sideDot);

            const exactContact=
              target.rad+rad;

            const snapZone=
              exactContact+
              1.25;

            if(currentSideDistance<=snapZone){
              const delta=
                Math.abs(
                  currentSideDistance-
                  exactContact
                );

              const score=
                delta+
                Math.max(
                  0,
                  Math.abs(along-axisLen*.5)-
                  axisLen*.65
                )*.08+
                (1-absDot)*.12;

              consider({
                mode:'parallel-touch',
                mesh,
                dx:pdx,
                dz:pdz,
                nx,
                nz,
                projectedX,
                projectedZ,
                exactContact,
                score
              });
            }
          }
        }

        // -------- CORNER / END SNAP --------
        // Lets the TIP of the new log touch the SIDE or END of another log,
        // useful for squares/walls on the ground.
        {
          const exactContact=
            target.rad+rad;

          const cornerSnapZone=
            exactContact+
            1.10;

          for(const endName of ['a','b']){
            const endPoint=
              endName==='a'
                ? target.a
                : target.b;

            const otherName=
              endName==='a'
                ? 'b'
                : 'a';

            const ex=endPoint.x;
            const ez=endPoint.z;

            const vx=ex-overlapA.x;
            const vz=ez-overlapA.z;

            let t=
              vx*dx+
              vz*dz;

            if(t<0)t=0;
            if(t>axisLen)t=axisLen;

            const px=
              overlapA.x+
              dx*t;

            const pz=
              overlapA.z+
              dz*t;

            let nx=
              ex-px;
            let nz=
              ez-pz;

            let dist=
              Math.hypot(nx,nz);

            if(dist<.0001){
              nx=-dz;
              nz= dx;
              const cross=
                currentDx*dz-
                currentDz*dx;
              if(cross<0){
                nx=-nx;
                nz=-nz;
              }
              dist=1;
            }else{
              nx/=dist;
              nz/=dist;
            }

            if(dist>cornerSnapZone)continue;

            const snappedEndX=
              px+nx*exactContact;

            const snappedEndZ=
              pz+nz*exactContact;

            const delta=
              Math.abs(dist-exactContact);

            // prefer this mode when logs are not parallel OR when the user is
            // clearly aiming the tip near another log/corner.
            const score=
              delta+
              absDot*.18+
              Math.abs(t-axisLen*.5)*.015;

            consider({
              mode:'corner-touch',
              mesh,
              endName,
              otherName,
              endX:snappedEndX,
              endZ:snappedEndZ,
              score
            });
          }
        }
      }

      if(!best)return target;

      const half=
        target.len*.5;

      if(best.mode==='parallel-touch'){
        const snappedCenterX=
          best.projectedX+
          best.nx*
          best.exactContact;

        const snappedCenterZ=
          best.projectedZ+
          best.nz*
          best.exactContact;

        target.a.x=
          snappedCenterX-
          best.dx*half;

        target.a.z=
          snappedCenterZ-
          best.dz*half;

        target.b.x=
          snappedCenterX+
          best.dx*half;

        target.b.z=
          snappedCenterZ+
          best.dz*half;
      }else if(best.mode==='corner-touch'){
        if(best.endName==='a'){
          target.a.x=best.endX;
          target.a.z=best.endZ;
          target.b.x=best.endX+currentDx*target.len;
          target.b.z=best.endZ+currentDz*target.len;
        }else{
          target.b.x=best.endX;
          target.b.z=best.endZ;
          target.a.x=best.endX-currentDx*target.len;
          target.a.z=best.endZ-currentDz*target.len;
        }
      }

      target.snapped=true;
      target.snappedTo=best.mesh;
      target.snapMode=best.mode;

      refreshTargetVertical(target);

      return target;
    }

    const overlapA=new THREE.Vector3();
    const overlapB=new THREE.Vector3();

    function validatePlacement(target){
      if(!target)return {valid:false,reason:"Posição inválida"};

      const logs=window.gameLumber?.placedLogs||[];
      for(const mesh of logs){
        if(!mesh?.parent||mesh.visible===false)continue;

        const len=Math.max(.4,Number(mesh.userData.length)||3.0);
        const rad=Math.max(.10,Number(mesh.userData.radius)||.22);

        mesh.updateMatrixWorld(true);
        overlapA.set(0,-len*.5,0).applyMatrix4(mesh.matrixWorld);
        overlapB.set(0, len*.5,0).applyMatrix4(mesh.matrixWorld);

        // If logs are vertically far apart, future stacked construction can
        // still be supported. Ground-level logs cannot occupy the same volume.
        const targetMidY=(target.a.y+target.b.y)*.5;
        const otherMidY=(overlapA.y+overlapB.y)*.5;
        if(Math.abs(targetMidY-otherMidY)>(target.rad+rad)*1.35)continue;

        const d=segmentDistanceXZ(
          target.a,
          target.b,
          overlapA,
          overlapB
        );

        // V58: geometry and collision now use the SAME radius.
        // Exact tangent contact (r1+r2) is legal. Only actual penetration
        // beyond a 2.5 mm numerical tolerance is blocked.
        const required=
          Math.max(
            .08,
            target.rad+
            rad-
            LOG_CONTACT_TOLERANCE
          );

        if(d<required){
          return {
            valid:false,
            reason:"Os troncos estão se atravessando"
          };
        }
      }

      return {valid:true,reason:""};
    }

    function setGhostValidity(g,valid){
      if(!g)return;
      const color=valid?0x72df9a:0xff5a4f;
      const emissive=valid?0x12351f:0x4a0b08;

      g.traverse(o=>{
        if(!o.isMesh)return;
        const mats=Array.isArray(o.material)?o.material:[o.material];
        mats.forEach(m=>{
          if(m?.color)m.color.setHex(color);
          if(m?.emissive){
            m.emissive.setHex(emissive);
            m.emissiveIntensity=.34;
          }
        });
      });
    }

    function updateGhost(){
      if(!positioning||placing)return;
      const g=ensureGhost();
      const target=computePlacement();
      if(!g||!target)return;

      const check=validatePlacement(target);
      placementValid=check.valid;
      placementBlockReason=check.reason;

      g.visible=true;
      g.position.lerp(target.position,.55);
      g.quaternion.slerp(target.quaternion,.55);
      setGhostValidity(g,placementValid);

      const pulse=.28+.07*(.5+.5*Math.sin(performance.now()*.006));
      g.traverse(o=>{
        if(!o.isMesh)return;
        const mats=Array.isArray(o.material)?o.material:[o.material];
        mats.forEach(m=>{if(m?.transparent)m.opacity=pulse});
      });

      if(hintTitle){
        hintTitle.textContent=
          placementValid
            ? (
                target.snapped
                  ? (target.snapMode==="corner-touch"?"COLADO • ponta na lateral":"COLADO • beirada com beirada")
                  : "Posicionando tronco"
              )
            : "Posição bloqueada";
      }

      if(hintText){
        hintText.textContent=
          placementValid
            ? (
                target.snapped
                  ? (target.snapMode==="corner-touch"?"ZERO brecha • ponta do tronco colada • clique para colocar":"ZERO brecha • alinhado paralelo • clique para colocar")
                  : "Chegue perto da lateral de outro tronco para ele grudar automaticamente"
              )
            : placementBlockReason;
      }
    }

    function cameraFollowsAnimatedBody(){
      tfp.visibleRoot.updateMatrixWorld(true);
      tfp.eyeSocket.getWorldPosition(eye);
      game.camera.position.copy(eye);
      game.camera.updateMatrixWorld(true);
    }

    function holdLogInFront(){
      const mesh=window.gameLumber?.carriedMesh;
      if(!mesh)return;
      tfp.visibleRoot.updateMatrixWorld(true);

      lHand.getWorldPosition(wpL);
      rHand.getWorldPosition(wpR);

      mid.copy(wpL).add(wpR).multiplyScalar(.5);
      axis.copy(wpR).sub(wpL);

      if(axis.lengthSq()<.005){
        const yaw=player.bodyYaw??player.yaw;
        axis.set(Math.cos(yaw),0,-Math.sin(yaw));
      }
      axis.normalize();

      // Let the animation decide the hand position. The trunk spans both hands.
      const targetPos=mid.clone().add(new THREE.Vector3(0,-.035,0));
      q.setFromUnitVectors(up,axis);

      mesh.visible=true;
      mesh.position.lerp(targetPos,.68);
      mesh.quaternion.slerp(q,.66);
      mesh.updateMatrixWorld(true);
    }

    // One shoulder anchor drives both the timber and the supporting arm.
    // All positions below are in world metres; no mesh or bone scale changes.
    function aimCarryBone(bone,child,target){
      bone.updateWorldMatrix(true,true);
      const origin=bone.getWorldPosition(new THREE.Vector3());
      const from=child.getWorldPosition(new THREE.Vector3()).sub(origin).normalize();
      const to=target.clone().sub(origin).normalize();
      const world=new THREE.Quaternion().setFromUnitVectors(from,to).multiply(bone.getWorldQuaternion(new THREE.Quaternion()));
      bone.quaternion.copy(bone.parent.getWorldQuaternion(new THREE.Quaternion()).invert().multiply(world));
      bone.updateWorldMatrix(false,true);
    }
    function holdLogOnShoulder(){
      const mesh=window.gameLumber?.carriedMesh;
      if(!mesh)return;
      const arm=tfp.bones.lArm,fore=tfp.bones.lFore;
      tfp.visibleRoot.updateMatrixWorld(true);
      arm.getWorldPosition(wpS);
      const yaw=player.bodyYaw??player.yaw;
      forward.set(-Math.sin(yaw),0,-Math.cos(yaw));
      right.set(Math.cos(yaw),0,-Math.sin(yaw));
      const rad=mesh.userData.radius||.22;
      // Cylinder radius at its middle is .92 of the base radius.
      // The lower bark rests on the shoulder cap, alongside the neck.
      const center=wpS.clone().addScaledVector(right,-(rad*.90+.035))
        .addScaledVector(up,rad*.55+.035);
      axis.copy(forward);
      mesh.visible=true;
      mesh.position.copy(center);
      mesh.quaternion.setFromUnitVectors(up,axis);
      mesh.updateMatrixWorld(true);
      const fingerDir=up.clone().multiplyScalar(.78).addScaledVector(right,-.625).normalize();
      const palm=center.clone().addScaledVector(forward,.30)
        .addScaledVector(right,-(rad*.73+.015)).addScaledVector(up,-(rad*.61+.012));
      const target=palm.clone().addScaledVector(fingerDir,-.075);
      const ap=wpS.clone(),bp=fore.getWorldPosition(new THREE.Vector3()),cp=lHand.getWorldPosition(new THREE.Vector3());
      const l1=ap.distanceTo(bp),l2=bp.distanceTo(cp),dir=target.clone().sub(ap);
      const d=clamp(dir.length(),Math.abs(l1-l2)+.001,l1+l2-.003);dir.normalize();
      const pole=ap.clone().addScaledVector(forward,.20).addScaledVector(right,-.24).addScaledVector(up,-.50);
      const bend=pole.sub(ap).addScaledVector(dir,-pole.dot(dir)).normalize();
      const along=(l1*l1-l2*l2+d*d)/(2*d),height=Math.sqrt(Math.max(0,l1*l1-along*along));
      aimCarryBone(arm,fore,ap.clone().addScaledVector(dir,along).addScaledVector(bend,height));
      aimCarryBone(fore,lHand,ap.clone().addScaledVector(dir,d));
      const hx=forward.clone(),hz=hx.clone().cross(fingerDir).normalize();
      const handQ=new THREE.Quaternion().setFromRotationMatrix(new THREE.Matrix4().makeBasis(hx,fingerDir,hz));
      lHand.quaternion.copy(lHand.parent.getWorldQuaternion(new THREE.Quaternion()).invert().multiply(handQ));
      // A broad open cup, not the tight closed grip used for the torch.
      for(const bone of tfp.localMesh.skeleton.bones){
        const match=bone.name.match(/LeftHand(Thumb|Index|Middle|Ring|Pinky)([123])$/);
        if(!match)continue;
        const digit=match[1],joint=Number(match[2]);
        bone.quaternion.identity();
        if(digit==='Thumb')bone.rotation.set(.18,0,joint===1?-.30:.12);
        else bone.rotation.set(joint===1?.20:.32,0,0);
      }
      tfp.visibleRoot.updateMatrixWorld(true);
      mesh.userData.shoulderSupport={shoulder:wpS.toArray(),palm:palm.toArray(),wrist:target.toArray()};
    }



    function enterPositioning(){
      if(!window.gameLumber?.carrying||placing)return false;
      positioning=true;
      placementValid=true;
      placementBlockReason="";
      stowTorch();
      stowAxeForPositioning();
      ensureGhost();
      useAction("carrying",true);
      setButtonState();

      if(hintTitle)hintTitle.textContent="Posicionando tronco";
      if(hintText)hintText.textContent="Mova a câmera para escolher o local • clique para colocar • G cancela";
      if(lumberStatus)lumberStatus.textContent="Posicionamento ativo • modelo transparente mostra onde ficará";
      if(status)status.textContent="Segurando o tronco à frente • clique para colocar";
      document.body.classList.add("log-positioning");
      return true;
    }

    function cancelPositioning(){
      if(!positioning||placing)return false;
      positioning=false;
      turnActive=false;
      removeGhost();
      restoreAxeAfterPositioning();
      useAction(isMoving()?"boxWalk":"shoulderIdle",true);
      setButtonState();
      document.body.classList.remove("log-positioning");

      if(lumberStatus)lumberStatus.textContent="Carregando tronco no ombro • G para posicionar";
      if(status)status.textContent="Tronco voltou para o ombro";
      return true;
    }

    function startPlacement(){
      if(!positioning||placing||!window.gameLumber?.carrying)return false;

      const target=computePlacement();
      if(!target)return false;

      const check=validatePlacement(target);
      placementValid=check.valid;
      placementBlockReason=check.reason;
      if(!placementValid){
        setGhostValidity(ghost,false);
        if(hintTitle)hintTitle.textContent="Posição bloqueada";
        if(hintText)hintText.textContent=placementBlockReason;
        if(lumberStatus)lumberStatus.textContent="Não pode sobrepor outro tronco";
        if(status)status.textContent=placementBlockReason;
        return false;
      }

      positioning=false;
      placing=true;
      placedThisAnimation=false;
      frozenPlacement={
        position:target.position.clone(),
        quaternion:target.quaternion.clone()
      };

      if(ghost){
        ghost.position.copy(frozenPlacement.position);
        ghost.quaternion.copy(frozenPlacement.quaternion);
      }

      useAction("holdingDown",true);
      setButtonState();

      if(hintTitle)hintTitle.textContent="Colocando o tronco";
      if(hintText)hintText.textContent="O personagem está baixando o tronco no local escolhido";
      if(lumberStatus)lumberStatus.textContent="Baixando tronco…";
      if(status)status.textContent="Colocando o tronco no chão";
      return true;
    }

    function solidifyPlacement(){
      if(placedThisAnimation||!placing||!frozenPlacement)return;
      const released=window.gameLumber?.releaseCarriedLog?.();
      if(!released?.mesh)return;

      placedThisAnimation=true;
      const mesh=released.mesh;
      mesh.visible=true;
      mesh.position.copy(frozenPlacement.position);
      mesh.quaternion.copy(frozenPlacement.quaternion);
      mesh.castShadow=true;
      mesh.receiveShadow=true;
      mesh.frustumCulled=true;
      mesh.updateMatrixWorld(true);

      window.gameLumber?.registerPlacedLog?.(mesh,released.tree);

      removeGhost();

      if(lumberStatus)lumberStatus.textContent="Tronco colocado no chão";
      if(status)status.textContent="Tronco posicionado • pronto para construção futura";
    }

    function finishPlacement(){
      if(!placing)return;
      solidifyPlacement();
      placing=false;
      positioning=false;
      frozenPlacement=null;
      stopAll();
      restoreTorch();
      restoreAxeAfterPositioning();
      document.body.classList.remove("log-positioning");
      setButtonState();
      if(hint)hint.classList.remove("visible");
    }

    mixer.addEventListener("finished",e=>{
      if(e.action===actions.holdingDown){
        finishPlacement();
      }else if(e.action===actions.turn){
        turnActive=false;
        if(positioning&&!placing){
          useAction(isMoving()?"walking":"carrying",true);
        }
      }
    });

    function updateAnimationState(dt){
      const carrying=!!window.gameLumber?.carrying;

      if(carrying&&!lastCarryingState){
        stowTorch();
      }
      if(!carrying&&lastCarryingState&&!placing){
        stopAll();
        removeGhost();
        positioning=false;
        restoreTorch();
        restoreAxeAfterPositioning();
      }
      lastCarryingState=carrying;

      if(!carrying&&!placing){
        setButtonState();
        return;
      }

      const moving=isMoving();
      const yawDelta=wrap(player.yaw-lastYaw);
      const yawSpeed=Math.abs(yawDelta)/Math.max(.001,dt);
      lastYaw=player.yaw;
      turnCooldown=Math.max(0,turnCooldown-dt);

      if(placing){
        if(currentKey!=="holdingDown")useAction("holdingDown",true);
      }else if(positioning){
        if(moving){
          turnActive=false;
          useAction("walking");
        }else if(!turnActive&&yawSpeed>1.05&&turnCooldown<=0){
          turnActive=true;
          turnCooldown=.42;
          useAction("turn",true);
        }else if(!turnActive){
          useAction("carrying");
        }
      }else{
        if(currentAction)stopAll(); // base locomotion plus shoulder support IK
      }

      mixer.update(dt);

      // The animation may rotate hips/spine, so keep the FPS camera attached
      // to the actual animated EyeSocket while retaining the player's look yaw/pitch.
      cameraFollowsAnimatedBody();

      if(placing){
        // Follow both animated hands until the log reaches the ground.
        if(window.gameLumber?.carrying)holdLogInFront();

        const progress=actions.holdingDown.time/Math.max(.001,clips.holdingDown.duration);
        if(progress>=.72)solidifyPlacement();
      }else if(positioning){
        holdLogInFront();
        updateGhost();
      }else{
        holdLogOnShoulder();

        // The LEFT arm/shoulder owns the trunk.
        // The RIGHT arm keeps the existing axe grip/IK from the V20 system.
        window.gameRightHand?.sync?.();
      }

      setButtonState();
    }

    // Run after all existing avatar/zombie/hit/lenhador systems.
    const previousUpdate=window.__updateAnimatedAvatar;
    window.__updateAnimatedAvatar=(...args)=>{
      // Movement has already been calculated by the base game at this point.
      // Resolve placed-log collision BEFORE the body/camera use player.x/z.
      resolvePlacedLogCollisions();

      previousUpdate?.(...args);
      const dt=Math.min(.05,Math.max(0,args[2]||0));

      // If the player is receiving a zombie hit, let that reaction own the body.
      // The log still follows the resulting hands/shoulder.
      if(window.gamePlayerHit?.active){
        if(window.gameLumber?.carrying){
          if(positioning||placing)holdLogInFront();
          else holdLogOnShoulder();
        }
        return;
      }

      updateAnimationState(dt);
    };


    // ----------------------------------------------------------
    // PLAYER <-> PLACED LOG COLLISION
    // Horizontal logs behave like low solid capsules.
    // If the player's FEET are above the local top of the log,
    // collision is skipped, so a single log can be jumped over.
    // ----------------------------------------------------------
    const colA=new THREE.Vector3();
    const colB=new THREE.Vector3();
    const colAB=new THREE.Vector3();
    const colClosest=new THREE.Vector3();
    const colPush=new THREE.Vector3();

    function resolvePlacedLogCollisions(){
      const logs=window.gameLumber?.placedLogs;
      if(!logs?.length)return;

      const playerRadius=Math.max(.28,Number(player.radius)||.42);

      // visibleRoot.y is the controller's feet height. Because this function
      // runs before the current frame avatar update, it represents the last
      // completed frame and is stable enough for jump gating.
      const feetY=tfp.visibleRoot?.position?.y ?? game.groundY(player.x,player.z);

      for(const mesh of logs){
        if(!mesh?.parent || mesh.visible===false)continue;

        const len=Math.max(.4,Number(mesh.userData.length)||3.0);
        const rad=Math.max(.10,Number(mesh.userData.radius)||.22);

        mesh.updateMatrixWorld(true);
        colA.set(0,-len*.5,0).applyMatrix4(mesh.matrixWorld);
        colB.set(0, len*.5,0).applyMatrix4(mesh.matrixWorld);

        // Closest point to player in the horizontal XZ plane.
        const abx=colB.x-colA.x;
        const abz=colB.z-colA.z;
        const ab2=abx*abx+abz*abz;
        let t=0;
        if(ab2>.000001){
          t=((player.x-colA.x)*abx+(player.z-colA.z)*abz)/ab2;
          t=clamp(t,0,1);
        }

        colClosest.set(
          colA.x+abx*t,
          colA.y+(colB.y-colA.y)*t,
          colA.z+abz*t
        );

        const localTopY=colClosest.y+rad;

        // This is what makes jumping over one low log possible.
        // Once the character's feet clear the top, the trunk stops blocking.
        if(feetY>localTopY+.07)continue;

        let dx=player.x-colClosest.x;
        let dz=player.z-colClosest.z;
        let dist=Math.hypot(dx,dz);
        const minDist=playerRadius+rad*.92;

        if(dist>=minDist)continue;

        if(dist<.0001){
          // Degenerate case: player center exactly over the log axis.
          // Push perpendicular to the log.
          dx=-abz;
          dz=abx;
          dist=Math.hypot(dx,dz)||1;
        }

        const nx=dx/dist,nz=dz/dist;
        const push=minDist-dist+.012;

        player.x+=nx*push;
        player.z+=nz*push;
      }
    }

    function togglePositioning(){
      if(!window.gameLumber?.carrying||placing)return;
      if(positioning)cancelPositioning();
      else enterPositioning();
    }

    placeBtn?.addEventListener("click",togglePositioning);
    mobileConfirm?.addEventListener("click",startPlacement);

    window.addEventListener("keydown",e=>{
      if(e.repeat)return;

      if(e.code==="KeyG"){
        if(window.gameLumber?.carrying&&!window.gameInventory?.isOpen&&!window.gameCraft?.active){
          e.preventDefault();
          e.stopImmediatePropagation();
          togglePositioning();
        }
        return;
      }

      if(e.code==="Escape"&&positioning&&!placing){
        e.preventDefault();
        cancelPositioning();
      }
    },true);

    // With Pointer Lock already active, left click confirms the transparent preview.
    window.addEventListener("pointerdown",e=>{
      if(!positioning||placing)return;
      if(e.pointerType==="mouse"&&e.button!==0)return;
      if(e.target!==canvas)return;

      e.preventDefault();
      e.stopImmediatePropagation();
      startPlacement();
    },true);

    window.addEventListener("game:log-picked",()=>{
      lastCarryingState=true;
      stowTorch();

      // V33: leave the axe equipped in the right hand while the
      // log is on the left shoulder.
      stopAll();
      window.gameRightHand?.sync?.();
      setButtonState();
    });

    window.gameLogPlacement={
      get active(){return positioning},
      get placing(){return placing},
      get preview(){return ghost},
      enter:enterPositioning,
      cancel:cancelPositioning,
      place:startPlacement,
      animations:{...SOURCES}
    };

    setButtonState();

    if(status){
      status.textContent="Construção com tronco pronta • G para posicionar quando estiver carregando";
    }
  }catch(err){
    console.error("Construção com tronco:",err);
    if(status)status.textContent+=" • posicionamento indisponível: "+String(err?.message||err);
  }
})();
